import {NextResponse} from "next/server";
import {db} from "@atlas/db";
import {resolveWorkspaceContext} from "@atlas/context";
import {deriveAtlasActivity} from "@atlas/activity";
import {optionalAtlasPrincipal} from "@/lib/session";

export const runtime="nodejs";
export async function GET(){
  const principal=await optionalAtlasPrincipal();if(!principal)return NextResponse.json({availability:"unauthorized",events:[]},{status:401});
  try{const context=await resolveWorkspaceContext(db(),principal),events=deriveAtlasActivity(context,100);return NextResponse.json({availability:"value",events},{headers:{"cache-control":"no-store"}})}
  catch{return NextResponse.json({availability:"unavailable",events:[]},{status:503})}
}

import {NextResponse} from "next/server";import {db} from "@atlas/db";import {resolveWorkflowApproval} from "@atlas/approvals";import {optionalAtlasPrincipal} from "@/lib/session";
export const runtime="nodejs";
export async function POST(request:Request,{params}:{params:Promise<{id:string;decision:string}>}){const principal=await optionalAtlasPrincipal();if(!principal)return NextResponse.json({message:"Authentication required."},{status:401});const route=await params;if(route.decision!=="approve"&&route.decision!=="reject")return NextResponse.json({message:"Invalid decision."},{status:400});const form=await request.formData(),note=String(form.get("note")||"").slice(0,500);try{await resolveWorkflowApproval(db(),principal,route.id,route.decision==="approve"?"approved":"rejected",note||undefined);return NextResponse.redirect(new URL("/app/approvals",request.url),303)}catch(error){const message=error instanceof Error?error.message:"Approval failed";return NextResponse.json({message},{status:message==="approval-permission-denied"?403:409})}}

import {NextResponse} from "next/server";
import {db} from "@atlas/db";
import {resolveWorkspaceContext} from "@atlas/context";
import {answerAtlas} from "@atlas/ask-atlas";
import {AuditRepository} from "@atlas/repositories";
import {optionalAtlasPrincipal} from "@/lib/session";

export const runtime="nodejs";
export async function POST(request:Request){
  const principal=await optionalAtlasPrincipal();if(!principal)return NextResponse.json({message:"Authentication required."},{status:401});
  const body=await request.json().catch(()=>({})),question=typeof body.question==="string"?body.question.trim():"";
  if(!question||question.length>2000)return NextResponse.json({message:"Question must be between 1 and 2000 characters."},{status:400});
  const sql=db(),context=await resolveWorkspaceContext(sql,principal),answer=answerAtlas(context,question);
  await new AuditRepository(sql).record({tenantId:principal.tenantId,workspaceId:principal.workspaceId},{actorId:principal.userId,action:"atlas.ask",targetType:"workspace",targetId:principal.workspaceId,metadata:{intent:answer.intent,evidenceCount:answer.evidence.length,surface:"product-next"}});
  return NextResponse.json(answer,{headers:{"cache-control":"no-store"}});
}

import {NextResponse} from "next/server";
import {db} from "@atlas/db";
import {UserRepository,MembershipRepository} from "@atlas/repositories";
import {verifyPassword,createSession} from "@atlas/auth";
import {atlasSessionCookieName} from "@/lib/session";

export const runtime="nodejs";
function scopes(role:string){if(role==="owner")return["*"];if(role==="admin")return["today:read","business:read","business:write","agents:read","approvals:manage","integrations:read","integrations:write"];if(role==="operator")return["today:read","business:read","business:write","agents:read","integrations:read"];if(role==="member")return["today:read","business:read","business:write"];return["today:read","business:read"]}

export async function POST(request:Request){
  const secret=process.env.ATLAS_AUTH_SECRET;if(!process.env.DATABASE_URL||!secret||secret.length<32)return NextResponse.json({message:"Connected runtime is not configured."},{status:503});
  const form=await request.formData(),email=String(form.get("email")||"").trim().toLowerCase(),password=String(form.get("password")||"");
  const user=await new UserRepository(db()).findByEmail(email);
  if(!user?.passwordHash||!verifyPassword(password,user.passwordHash))return NextResponse.redirect(new URL("/login?error=1",request.url),303);
  const membership=await new MembershipRepository(db()).firstActiveForUser(user.id);if(!membership)return NextResponse.redirect(new URL("/login?error=1",request.url),303);
  const token=createSession({userId:user.id,tenantId:membership.tenantId,workspaceId:membership.workspaceId,role:membership.role,scopes:scopes(membership.role)},secret);
  const response=NextResponse.redirect(new URL("/app/today",request.url),303);
  response.cookies.set(atlasSessionCookieName,token,{httpOnly:true,sameSite:"lax",secure:process.env.NODE_ENV==="production",path:"/",maxAge:43200});
  return response;
}

import {NextResponse} from "next/server";
import {db} from "@atlas/db";
import {BillingRepository,WorkspaceRepository,UserRepository} from "@atlas/repositories";
import {createStripeBillingRuntime,stripeBillingConfigured} from "@atlas/billing-stripe";
import {isAtlasPlan} from "@atlas/entitlements";
import {optionalAtlasPrincipal} from "@/lib/session";
import {canManageBilling} from "@/lib/permissions";

export const runtime="nodejs";
export async function POST(request:Request,{params}:{params:Promise<{action:string}>}){
  const principal=await optionalAtlasPrincipal();if(!principal)return NextResponse.json({message:"Authentication required."},{status:401});
  if(!canManageBilling(principal))return NextResponse.json({message:"Admin role is required."},{status:403});
  if(!stripeBillingConfigured())return NextResponse.json({message:"Stripe billing is not configured."},{status:503});
  const route=await params,scope={tenantId:principal.tenantId,workspaceId:principal.workspaceId},sql=db(),workspace=await new WorkspaceRepository(sql).findScoped(scope.tenantId,scope.workspaceId);
  if(!workspace)return NextResponse.json({message:"Workspace not found."},{status:404});
  await new BillingRepository(sql).ensure(scope,workspace.planId,workspace.billingStatus,workspace.trialEndsAt);
  const stripe=createStripeBillingRuntime(sql);
  try{
    if(route.action==="portal"){const result=await stripe.createPortal(scope);return NextResponse.redirect(result.url,303)}
    if(route.action==="cancel"){await stripe.cancelAtPeriodEnd(scope);return NextResponse.redirect(new URL("/app/billing",request.url),303)}
    if(route.action==="reactivate"){await stripe.reactivate(scope);return NextResponse.redirect(new URL("/app/billing",request.url),303)}
    const form=await request.formData(),plan=String(form.get("plan")||"");if(!isAtlasPlan(plan))return NextResponse.json({message:"Unknown AtlasOS plan."},{status:400});
    if(route.action==="plan"){await stripe.changePlan(scope,plan);return NextResponse.redirect(new URL("/app/billing",request.url),303)}
    if(route.action==="checkout"){const user=await new UserRepository(sql).findById(principal.userId);if(!user)return NextResponse.json({message:"User not found."},{status:404});const result=await stripe.createCheckout(scope,{plan,createdBy:principal.userId,email:user.email});return NextResponse.redirect(result.url,303)}
    return NextResponse.json({message:"Unknown billing action."},{status:404});
  }catch(error){return NextResponse.json({message:error instanceof Error?error.message:"Billing action failed."},{status:409})}
}

