import {NextResponse} from "next/server";import {db} from "@atlas/db";import {createStripeBillingRuntime,stripeBillingConfigured} from "@atlas/billing-stripe";
export const runtime="nodejs";
export async function POST(request:Request){if(!stripeBillingConfigured())return NextResponse.json({message:"Stripe billing is not configured."},{status:503});const signature=request.headers.get("stripe-signature");if(!signature)return NextResponse.json({message:"Invalid Stripe webhook."},{status:400});const raw=await request.text();try{const result=await createStripeBillingRuntime(db()).handleWebhook(raw,signature);return NextResponse.json({received:true,duplicate:result.duplicate})}catch(error){const message=error instanceof Error?error.message:"stripe-webhook-failed",invalid=message.startsWith("stripe-signature")||message.includes("event-json")||message.includes("event-invalid")||message.includes("object-invalid");return NextResponse.json({message:invalid?"Invalid Stripe webhook.":"Stripe webhook could not be processed."},{status:invalid?400:500})}}

