export type GrowthChannel = 'x' | 'linkedin' | 'instagram' | 'facebook' | 'threads' | 'reddit';
export type AttributionModel = 'direct' | 'first_touch' | 'last_touch' | 'assisted';
export type AttributionEventType = 'click' | 'signup' | 'activation' | 'demo_requested' | 'trial_started' | 'purchase';
export interface ProductDNA {id:string;productName:string;url:string;description:string;audience:string[];pains:string[];differentiators:string[];competitors:string[];proof:string[];voice:string[];prohibitedClaims:string[];primaryCta:string;updatedAt:string;}
export interface GrowthOpportunity {id:string;channel:'x'|'reddit';author:string;text:string;url:string;intentScore:number;fitScore:number;riskScore:number;totalScore:number;rationale:string;suggestedReply:string;status:'new'|'approved'|'replied'|'skipped';discoveredAt:string;}
export interface AttributionEvent {id:string;type:AttributionEventType;anonymousId?:string;userId?:string;campaignId?:string;contentId?:string;angleId?:string;source?:string;value?:number;currency?:string;occurredAt:string;}
export interface AttributionCredit {conversionEventId:string;conversionType:Exclude<AttributionEventType,'click'>;campaignId?:string;contentId?:string;source?:string;weight:number;revenue:number;}
export interface GrowthMemoryFact {id:string;statement:string;confidence:number;sampleSize:number;evidence:string[];scope:'channel'|'angle'|'audience'|'cta'|'timing';}
export function opportunityScore(intent:number,fit:number,risk:number):number{return Math.round(Math.max(0,Math.min(100,intent*.46+fit*.44+(100-risk)*.10)));}
export function budgetRecommendation(input:{current:number;cpa:number;targetCpa:number;conversions:number;maxDailyIncreasePct?:number}):number{const maxIncrease=input.maxDailyIncreasePct??20;if(input.conversions<5)return input.current;if(input.cpa<=input.targetCpa*.8)return Math.round(input.current*(1+maxIncrease/100));if(input.cpa>input.targetCpa*1.2)return Math.max(1,Math.round(input.current*.85));return input.current;}
const when=(event:AttributionEvent)=>{const v=Date.parse(event.occurredAt);return Number.isFinite(v)?v:0};
const identity=(event:AttributionEvent)=>event.userId?`user:${event.userId}`:event.anonymousId?`anon:${event.anonymousId}`:null;
const direct=(event:AttributionEvent):AttributionCredit[]=>!event.campaignId&&!event.contentId&&!event.source?[]:[{conversionEventId:event.id,conversionType:event.type as AttributionCredit['conversionType'],campaignId:event.campaignId,contentId:event.contentId,source:event.source,weight:1,revenue:event.type==='purchase'?(event.value??0):0}];
export function calculateAttribution(events:AttributionEvent[],model:AttributionModel):AttributionCredit[]{const ordered=[...events].sort((a,b)=>when(a)-when(b));const credits:AttributionCredit[]=[];for(const conversion of ordered.filter(e=>e.type!=='click')){if(model==='direct'){credits.push(...direct(conversion));continue}const who=identity(conversion);if(!who){credits.push(...direct(conversion));continue}const touches=ordered.filter(e=>e.type==='click'&&identity(e)===who&&when(e)<=when(conversion)&&Boolean(e.campaignId||e.contentId||e.source));if(!touches.length){credits.push(...direct(conversion));continue}const selected=model==='first_touch'?[touches[0]]:model==='last_touch'?[touches[touches.length-1]]:touches;const weight=1/selected.length;const revenue=conversion.type==='purchase'?(conversion.value??0):0;for(const touch of selected)credits.push({conversionEventId:conversion.id,conversionType:conversion.type as AttributionCredit['conversionType'],campaignId:touch.campaignId,contentId:touch.contentId,source:touch.source,weight,revenue:revenue*weight});}return credits;}
export function summarizeAttribution(events:AttributionEvent[]){const clicks=events.filter(e=>e.type==='click').length;const signups=events.filter(e=>e.type==='signup').length;const purchases=events.filter(e=>e.type==='purchase');return{clicks,signups,activations:events.filter(e=>e.type==='activation').length,demoRequests:events.filter(e=>e.type==='demo_requested').length,trials:events.filter(e=>e.type==='trial_started').length,purchases:purchases.length,revenue:purchases.reduce((s,e)=>s+(e.value??0),0),conversionRate:clicks===0?0:Number(((signups/clicks)*100).toFixed(2))};}

import type {AtlasSql} from "../../db/src/index.js";
import {AuditRepository,IntegrationConnectionRepository,UsageRepository} from "../../repositories/src/index.js";
import type {ToolDefinition} from "../../agent-governance/src/index.js";
import type {ToolExecutionContext,ToolExecutor} from "../../workflow-runtime/src/index.js";
import {WorkflowRuntimeError} from "../../workflow-runtime/src/index.js";
import {
  IntegrationAdapterRegistry,
  assertActionAllowed,
  type IntegrationExecutionResult,
  type IntegrationHealth
} from "../../integrations-sdk/src/index.js";

const sensitiveKey=/(secret|token|password|authorization|cookie|api[-_]?key|credential|refresh)/i;

function safePrimitive(value:unknown):string|number|boolean|null{
  if(value===null||typeof value==="string"||typeof value==="number"||typeof value==="boolean")return value;
  return String(value);
}

export function sanitizeIntegrationData(value:unknown,depth=0):unknown{
  if(depth>4)return "[truncated]";
  if(Array.isArray(value))return value.slice(0,50).map(item=>sanitizeIntegrationData(item,depth+1));
  if(value&&typeof value==="object"){
    const result:Record<string,unknown>={};
    for(const [key,item] of Object.entries(value as Record<string,unknown>).slice(0,100)){
      if(sensitiveKey.test(key))continue;
      result[key]=sanitizeIntegrationData(item,depth+1);
    }
    return result;
  }
  if(typeof value==="string")return value.length>4096?value.slice(0,4096)+"…":value;
  return safePrimitive(value);
}

function safeErrorMessage(error:unknown){
  const message=error instanceof Error?error.message:"integration-execution-failed";
  return message
    .replace(/Bearer\s+[^\s]+/gi,"Bearer [redacted]")
    .replace(/(?:token|secret|password|api[-_]?key)=([^\s&]+)/gi,match=>match.split("=")[0]+"=[redacted]")
    .slice(0,500);
}

function classifyFailure(message:string){
  if(/timeout|aborted|econnreset|eai_again|enotfound|webhook-http-(429|502|503|504)|google-network|google-ambiguous|google-http-(429|500|502|503|504)/i.test(message))return "retryable" as const;
  return "non_retryable" as const;
}

function healthForFailure(message:string):IntegrationHealth{
  const reauthentication=/google-needs-reauthentication|google-http-401|invalid_grant/i.test(message);
  return{
    state:reauthentication?"needs_reauthentication":"error",
    message:message.slice(0,500),
    checkedAt:new Date().toISOString(),
    details:{category:classifyFailure(message)}
  };
}

export class IntegrationToolExecutor implements ToolExecutor{
  readonly connector:string;
  private readonly connections:IntegrationConnectionRepository;
  private readonly audit:AuditRepository;
  private readonly usage:UsageRepository;

  constructor(
    private readonly sql:AtlasSql,
    private readonly adapters:IntegrationAdapterRegistry,
    integrationId:string
  ){
    this.connector=integrationId;
    this.connections=new IntegrationConnectionRepository(sql);
    this.audit=new AuditRepository(sql);
    this.usage=new UsageRepository(sql);
  }

  async execute(tool:ToolDefinition,input:Record<string,unknown>,context:ToolExecutionContext):Promise<Record<string,unknown>>{
    const scope={tenantId:context.tenantId,workspaceId:context.workspaceId};
    const connection=await this.connections.findByIntegration(scope,this.connector);
    if(!connection)throw new WorkflowRuntimeError("non_retryable","integration-not-configured");
    if(connection.status==="not_configured")throw new WorkflowRuntimeError("non_retryable","integration-not-configured");
    if(connection.status==="needs_reauthentication")throw new WorkflowRuntimeError("non_retryable","integration-needs-reauthentication");
    if(connection.status==="error"&&connection.healthDetails.category!=="retryable")throw new WorkflowRuntimeError("non_retryable","integration-unhealthy");

    const adapter=this.adapters.get(this.connector);
    if(!adapter)throw new WorkflowRuntimeError("non_retryable","integration-adapter-not-registered");

    const actionId=tool.action;
    let capability;
    try{capability=assertActionAllowed(adapter,actionId)}
    catch{throw new WorkflowRuntimeError("non_retryable","integration-action-unsupported")}

    const missingCapabilityScopes=capability.requiredScopes.filter(scopeName=>!tool.scopes.includes(scopeName));
    if(missingCapabilityScopes.length){
      throw new WorkflowRuntimeError("non_retryable",`integration-capability-scopes-missing:${missingCapabilityScopes.join(",")}`);
    }
    if(capability.write&&!tool.isWrite){
      throw new WorkflowRuntimeError("non_retryable","integration-capability-write-mismatch");
    }
    const providerHighRisk=capability.risk==="high"||capability.risk==="critical";
    const declaredHighRisk=tool.risk==="high"||tool.risk==="critical";
    if(providerHighRisk&&!declaredHighRisk){
      throw new WorkflowRuntimeError("non_retryable","integration-capability-risk-mismatch");
    }

    const startedAt=Date.now();
    await this.audit.record(scope,{
      actorId:context.initiatedBy,
      action:"integration.execution_started",
      targetType:"integration_connection",
      targetId:connection.id,
      metadata:{integrationId:this.connector,workflowRunId:context.runId,workflowStepId:context.stepId,agentId:context.agentId,toolId:tool.id}
    });

    const config={...connection.config,secretReference:connection.secretReference};
    try{
      const result=await adapter.execute(
        actionId,
        input,
        {
          ...scope,
          connectionId:connection.id,
          actionId,
          idempotencyKey:context.idempotencyKey,
          initiatedBy:context.initiatedBy,
          agentId:context.agentId
        },
        config
      ) as IntegrationExecutionResult;

      const safeData=sanitizeIntegrationData(result.data) as Record<string,unknown>;
      await this.connections.updateHealth(scope,connection.id,{
        state:"connected",
        message:"Integration action completed successfully.",
        checkedAt:new Date().toISOString(),
        details:{status:result.status,actionId}
      });
      await this.audit.record(scope,{
        actorId:context.initiatedBy,
        action:"integration.execution_succeeded",
        targetType:"integration_connection",
        targetId:connection.id,
        metadata:{
          integrationId:this.connector,
          workflowRunId:context.runId,
          workflowStepId:context.stepId,
          agentId:context.agentId,
          toolId:tool.id,
          providerStatus:result.status,
          externalId:result.externalId??null,
          durationMs:Date.now()-startedAt
        }
      });
      await this.usage.record(scope,{metric:"external_actions",quantity:1,agentId:context.agentId,workflowId:context.runId,provider:this.connector,idempotencyKey:context.idempotencyKey});
      await this.usage.record(scope,{metric:"agent_runs",quantity:1,agentId:context.agentId,workflowId:context.runId,provider:this.connector,idempotencyKey:context.idempotencyKey});
      return{
        ok:result.ok,
        status:result.status,
        data:safeData,
        externalId:result.externalId??null,
        idempotencyKey:result.idempotencyKey,
        completedAt:result.completedAt
      };
    }catch(error){
      const message=safeErrorMessage(error);
      await this.connections.updateHealth(scope,connection.id,healthForFailure(message));
      await this.audit.record(scope,{
        actorId:context.initiatedBy,
        action:"integration.execution_failed",
        targetType:"integration_connection",
        targetId:connection.id,
        metadata:{
          integrationId:this.connector,
          workflowRunId:context.runId,
          workflowStepId:context.stepId,
          agentId:context.agentId,
          toolId:tool.id,
          category:classifyFailure(message),
          durationMs:Date.now()-startedAt
        }
      });
      throw new WorkflowRuntimeError(classifyFailure(message),message);
    }
  }
}

