    const secrets=new MemorySecretStore();
    const transport=new QueueTransport([]);
    const config={clientId:"client-id",clientSecret:"client-secret",redirectUri:"https://atlas.example.test/app/integrations/google/callback"};
    const service=new GoogleOAuthService(sql,secrets,transport,config,new GoogleTokenManager(sql,secrets,transport,config));
    const started=await service.begin(principal);
    const state=new URL(started.authorizationUrl).searchParams.get("state")??"";

    let tampered=false;
    try{await service.complete(principal,state+"x","valid-code")}catch(error){tampered=error instanceof Error&&error.message==="google-oauth-state-invalid-or-expired"}
    assert.equal(tampered,true);

    await sql`UPDATE atlas_oauth_transactions SET expires_at=now()-interval '1 minute' WHERE tenant_id=${principal.tenantId} AND workspace_id=${principal.workspaceId}`;
    let expired=false;
    try{await service.complete(principal,state,"valid-code")}catch(error){expired=error instanceof Error&&error.message==="google-oauth-state-invalid-or-expired"}
    assert.equal(expired,true);
    assert.equal(transport.requests.length,0);
  }finally{await closeDb()}
});

import {createHash,randomBytes,randomUUID} from "node:crypto";
import type {AtlasSql} from "../../db/src/index.js";
import type {TenantPrincipal} from "../../tenancy/src/index.js";
import type {SecretStore,SecretScope} from "../../secrets/src/index.js";
import {AuditRepository} from "../../repositories/src/index.js";
import {formBody,googleHttpError,parseGoogleJson,type GoogleHttpTransport} from "./transport.js";
import {GOOGLE_INTEGRATION_ID,GOOGLE_SCOPES,GoogleTokenManager,type GoogleOAuthConfig} from "./tokens.js";

const PROVIDER=GOOGLE_INTEGRATION_ID;
const AUTH_ENDPOINT="https://accounts.google.com/o/oauth2/v2/auth";
const TOKEN_ENDPOINT="https://oauth2.googleapis.com/token";
const GMAIL_PROFILE_ENDPOINT="https://gmail.googleapis.com/gmail/v1/users/me/profile";

function sha256(value:string){return createHash("sha256").update(value).digest().toString("base64url")}
function randomVerifier(){return randomBytes(48).toString("base64url")}

export class GoogleOAuthTransactionRepository{
  constructor(private readonly sql:AtlasSql){}

  async create(input:{
    tenantId:string;workspaceId:string;userId:string;stateHash:string;
    verifierSecretReference:string;expiresAt:string;
  }){
    const id=randomUUID();
    await this.sql`INSERT INTO atlas_oauth_transactions(
      id,tenant_id,workspace_id,user_id,provider,state_hash,verifier_secret_reference,expires_at
    ) VALUES(
      ${id},${input.tenantId},${input.workspaceId},${input.userId},${PROVIDER},${input.stateHash},${input.verifierSecretReference},${input.expiresAt}
    )`;
    return id;
  }

  async consume(input:{tenantId:string;workspaceId:string;userId:string;stateHash:string}){
    const rows=await this.sql`UPDATE atlas_oauth_transactions SET consumed_at=now()
      WHERE tenant_id=${input.tenantId}
        AND workspace_id=${input.workspaceId}
        AND user_id=${input.userId}
        AND provider=${PROVIDER}
        AND state_hash=${input.stateHash}
        AND consumed_at IS NULL
        AND expires_at>now()
      RETURNING id,verifier_secret_reference,expires_at`;
    return rows[0]??null;
  }
}

export interface GoogleOAuthBeginResult{authorizationUrl:string;expiresAt:string}
export interface GoogleOAuthCompleteResult{connectionId:string;accountEmail:string;scopes:string[]}

export class GoogleOAuthService{
  private readonly transactions:GoogleOAuthTransactionRepository;
  private readonly audit:AuditRepository;

  constructor(
    private readonly sql:AtlasSql,
    private readonly secrets:SecretStore,
    private readonly transport:GoogleHttpTransport,
    private readonly config:GoogleOAuthConfig,
    private readonly tokens:GoogleTokenManager
  ){
    this.transactions=new GoogleOAuthTransactionRepository(sql);
    this.audit=new AuditRepository(sql);
  }

  async begin(principal:TenantPrincipal):Promise<GoogleOAuthBeginResult>{
    const scope:SecretScope={tenantId:principal.tenantId,workspaceId:principal.workspaceId};
    const state=randomBytes(32).toString("base64url");
    const verifier=randomVerifier();
    const challenge=sha256(verifier);
    const verifierRef=await this.secrets.put(scope,verifier);
    const expiresAt=new Date(Date.now()+10*60_000).toISOString();
    try{
      await this.transactions.create({
        ...scope,userId:principal.userId,stateHash:sha256(state),
        verifierSecretReference:verifierRef,expiresAt
      });
    }catch(error){
      await this.secrets.delete(scope,verifierRef);
      throw error;
    }

    const url=new URL(AUTH_ENDPOINT);
    url.searchParams.set("client_id",this.config.clientId);
    url.searchParams.set("redirect_uri",this.config.redirectUri);
    url.searchParams.set("response_type","code");
    url.searchParams.set("scope",GOOGLE_SCOPES.join(" "));
    url.searchParams.set("access_type","offline");
    url.searchParams.set("include_granted_scopes","true");
    url.searchParams.set("prompt","consent");
    url.searchParams.set("state",state);
    url.searchParams.set("code_challenge",challenge);
    url.searchParams.set("code_challenge_method","S256");

    await this.audit.record(scope,{
      actorId:principal.userId,
      action:"integration.oauth_started",
      targetType:"integration",
      targetId:PROVIDER,
      metadata:{provider:PROVIDER,expiresAt,scopeCount:GOOGLE_SCOPES.length}
    });
    return{authorizationUrl:url.toString(),expiresAt};
  }

  async complete(principal:TenantPrincipal,state:string,code:string):Promise<GoogleOAuthCompleteResult>{
    if(state.length<20||state.length>512||code.length<5||code.length>4096)throw new Error("google-oauth-callback-invalid");
    const scope:SecretScope={tenantId:principal.tenantId,workspaceId:principal.workspaceId};
    const transaction=await this.transactions.consume({...scope,userId:principal.userId,stateHash:sha256(state)});
    if(!transaction)throw new Error("google-oauth-state-invalid-or-expired");
    const verifierRef=String(transaction.verifier_secret_reference);
    const verifier=await this.secrets.get(scope,verifierRef);
    if(!verifier)throw new Error("google-oauth-verifier-unavailable");

    try{
      const tokenResponse=await this.transport.request({
        url:TOKEN_ENDPOINT,
        method:"POST",
        headers:{"content-type":"application/x-www-form-urlencoded","accept":"application/json"},
        body:formBody({
          client_id:this.config.clientId,
          client_secret:this.config.clientSecret,
          code,
          code_verifier:verifier,
          grant_type:"authorization_code",
          redirect_uri:this.config.redirectUri
        })
      });
      if(tokenResponse.status<200||tokenResponse.status>=300)throw googleHttpError(tokenResponse);
      const token=parseGoogleJson<any>(tokenResponse);
      if(typeof token.access_token!=="string")throw new Error("google-oauth-access-token-missing");

      const profileResponse=await this.transport.request({
        url:GMAIL_PROFILE_ENDPOINT,
        method:"GET",
        headers:{authorization:`Bearer ${token.access_token}`,"accept":"application/json"}
      });
      if(profileResponse.status<200||profileResponse.status>=300)throw googleHttpError(profileResponse);
      const profile=parseGoogleJson<any>(profileResponse);
      if(typeof profile.emailAddress!=="string"||!profile.emailAddress.includes("@"))throw new Error("google-account-email-missing");

      const scopes=typeof token.scope==="string"?token.scope.split(/\s+/).filter(Boolean):[...GOOGLE_SCOPES];
      const connection=await this.tokens.persistAuthorization(scope,{
        accessToken:token.access_token,
        refreshToken:typeof token.refresh_token==="string"?token.refresh_token:null,
        expiresIn:Number(token.expires_in??3600),
        tokenType:typeof token.token_type==="string"?token.token_type:"Bearer",
        scopes,
        accountEmail:profile.emailAddress
      });
      await this.audit.record(scope,{
        actorId:principal.userId,
        action:"integration.oauth_connected",
        targetType:"integration_connection",
        targetId:connection.id,
        metadata:{provider:PROVIDER,accountEmail:profile.emailAddress,scopeCount:scopes.length}
      });
      return{connectionId:connection.id,accountEmail:profile.emailAddress,scopes};
    }finally{
      await this.secrets.delete(scope,verifierRef);
    }
  }
}

import type {AtlasSql} from "../../db/src/index.js";
import {EncryptedPostgresSecretStore,keyringFromEnvironment} from "../../secrets/src/index.js";
import {GoogleWorkspaceAdapter} from "./adapter.js";
import {GoogleOAuthService} from "./oauth.js";
import {FetchGoogleHttpTransport} from "./transport.js";
import {googleOAuthConfigFromEnv,GoogleTokenManager} from "./tokens.js";

export function googleRuntimeConfigured(env=process.env){
  try{
    googleOAuthConfigFromEnv(env);
    keyringFromEnvironment(env);
    return true;
  }catch{return false}
}

export function createGoogleRuntime(sql:AtlasSql){
  const config=googleOAuthConfigFromEnv();
  const secrets=new EncryptedPostgresSecretStore(sql);
  const transport=new FetchGoogleHttpTransport();
  const tokens=new GoogleTokenManager(sql,secrets,transport,config);
  const adapter=new GoogleWorkspaceAdapter(sql,tokens,transport);
  const oauth=new GoogleOAuthService(sql,secrets,transport,config,tokens);
  return{config,secrets,transport,tokens,adapter,oauth};
}

import test from "node:test";
import assert from "node:assert/strict";
import {randomUUID} from "node:crypto";
import {db,closeDb} from "../../db/src/index.js";
import {UserRepository,IntegrationConnectionRepository,provisionWorkspace} from "../../repositories/src/index.js";
import {MemorySecretStore} from "../../secrets/src/index.js";
import {GoogleReauthenticationRequired,GoogleTokenManager} from "./tokens.js";
import type {GoogleHttpRequest,GoogleHttpResponse,GoogleHttpTransport} from "./transport.js";

class QueueTransport implements GoogleHttpTransport{
  requests:GoogleHttpRequest[]=[];
  constructor(private readonly responses:GoogleHttpResponse[]){}
  async request(input:GoogleHttpRequest){
    this.requests.push(input);
    const next=this.responses.shift();if(!next)throw new Error("unexpected-google-request");return next;
  }
}
const response=(status:number,body:unknown):GoogleHttpResponse=>({status,body:JSON.stringify(body),headers:{}});

test("Google token manager refreshes expired encrypted token in place",async()=>{
  if(!process.env.DATABASE_URL)return;
  const sql=db();
  try{
    const user=await new UserRepository(sql).create({email:`refresh-${randomUUID()}@example.test`,passwordHash:"test"});
    const workspace=await provisionWorkspace(sql,{userId:user.id,workspaceName:`Refresh ${randomUUID().slice(0,8)}`,verticalId:"founder",moduleIds:["today"]});
    const scope={tenantId:workspace.tenantId,workspaceId:workspace.workspaceId};
    const secrets=new MemorySecretStore();
    const reference=await secrets.put(scope,JSON.stringify({accessToken:"expired",refreshToken:"refresh-secret",expiresAt:Date.now()-1000,tokenType:"Bearer",scopes:["scope-a"]}));
    const connection=await new IntegrationConnectionRepository(sql).upsert(scope,{integrationId:"google-workspace",status:"connected",externalAccountRef:"owner@example.test",secretReference:reference,config:{scopes:["scope-a"]}});
    const transport=new QueueTransport([response(200,{access_token:"new-access",expires_in:3600,token_type:"Bearer",scope:"scope-a"})]);
    const manager=new GoogleTokenManager(sql,secrets,transport,{clientId:"client",clientSecret:"client-secret",redirectUri:"https://atlas.example.test/callback"});

    assert.equal(await manager.getAccessToken(scope,connection.id),"new-access");
    const saved=await secrets.get(scope,reference);
    assert.equal(saved?.includes("new-access"),true);
    assert.equal(saved?.includes("refresh-secret"),true);
    assert.equal(transport.requests.length,1);
    assert.equal(transport.requests[0].body?.includes("refresh-secret"),true);
  }finally{await closeDb()}
});

test("Google invalid_grant transitions connection to needs_reauthentication",async()=>{
  if(!process.env.DATABASE_URL)return;
  const sql=db();
  try{
    const user=await new UserRepository(sql).create({email:`invalid-grant-${randomUUID()}@example.test`,passwordHash:"test"});
    const workspace=await provisionWorkspace(sql,{userId:user.id,workspaceName:`Invalid Grant ${randomUUID().slice(0,8)}`,verticalId:"founder",moduleIds:["today"]});
    const scope={tenantId:workspace.tenantId,workspaceId:workspace.workspaceId};
    const secrets=new MemorySecretStore();
    const reference=await secrets.put(scope,JSON.stringify({accessToken:"expired",refreshToken:"revoked",expiresAt:Date.now()-1000,tokenType:"Bearer",scopes:[]}));
    const repo=new IntegrationConnectionRepository(sql);
    const connection=await repo.upsert(scope,{integrationId:"google-workspace",status:"connected",externalAccountRef:"owner@example.test",secretReference:reference,config:{}});
    const manager=new GoogleTokenManager(sql,secrets,new QueueTransport([response(400,{error:"invalid_grant"})]),{clientId:"client",clientSecret:"client-secret",redirectUri:"https://atlas.example.test/callback"});

    let reauth=false;
    try{await manager.getAccessToken(scope,connection.id)}catch(error){reauth=error instanceof GoogleReauthenticationRequired}
    assert.equal(reauth,true);
    assert.equal((await repo.findScoped(scope,connection.id))?.status,"needs_reauthentication");
  }finally{await closeDb()}
});

import type {AtlasSql} from "../../db/src/index.js";
import {IntegrationConnectionRepository,type StoredIntegrationConnection} from "../../repositories/src/index.js";
import type {SecretStore,SecretScope} from "../../secrets/src/index.js";
import {formBody,googleHttpError,parseGoogleJson,type GoogleHttpTransport} from "./transport.js";

export const GOOGLE_INTEGRATION_ID="google-workspace";
export const GOOGLE_SCOPES=[
  "https://www.googleapis.com/auth/gmail.readonly",
  "https://www.googleapis.com/auth/gmail.send",
  "https://www.googleapis.com/auth/calendar.events"
] as const;

export interface GoogleOAuthConfig{
  clientId:string;
  clientSecret:string;
  redirectUri:string;
}
export interface GoogleTokenSecret{
  accessToken:string;
  refreshToken:string|null;
  expiresAt:number;
  tokenType:string;
  scopes:string[];
}

export class GoogleReauthenticationRequired extends Error{
  constructor(message="google-needs-reauthentication"){super(message);this.name="GoogleReauthenticationRequired"}
}

export function googleOAuthConfigFromEnv(env=process.env):GoogleOAuthConfig{
  const clientId=env.GOOGLE_CLIENT_ID?.trim()??"";
  const clientSecret=env.GOOGLE_CLIENT_SECRET?.trim()??"";
  const redirectUri=env.GOOGLE_OAUTH_REDIRECT_URI?.trim()??"";
  if(!clientId||!clientSecret||!redirectUri)throw new Error("google-oauth-not-configured");
  let parsed:URL;
  try{parsed=new URL(redirectUri)}catch{throw new Error("google-oauth-redirect-invalid")}
  if(env.NODE_ENV==="production"&&parsed.protocol!=="https:")throw new Error("google-oauth-https-redirect-required");
  if(!["http:","https:"].includes(parsed.protocol))throw new Error("google-oauth-redirect-invalid");
  return{clientId,clientSecret,redirectUri};
}

function parseSecret(value:string|null):GoogleTokenSecret|null{
  if(!value)return null;
  try{
    const parsed=JSON.parse(value) as Partial<GoogleTokenSecret>;
    if(typeof parsed.accessToken!=="string"||typeof parsed.expiresAt!=="number")return null;
    return{
      accessToken:parsed.accessToken,
      refreshToken:typeof parsed.refreshToken==="string"?parsed.refreshToken:null,
      expiresAt:parsed.expiresAt,
      tokenType:typeof parsed.tokenType==="string"?parsed.tokenType:"Bearer",
      scopes:Array.isArray(parsed.scopes)?parsed.scopes.filter((item):item is string=>typeof item==="string"):[]
    };
  }catch{return null}
}

export class GoogleTokenManager{
  private readonly connections:IntegrationConnectionRepository;
  constructor(
    private readonly sql:AtlasSql,
    private readonly secrets:SecretStore,
    private readonly transport:GoogleHttpTransport,
    private readonly oauth:GoogleOAuthConfig
  ){this.connections=new IntegrationConnectionRepository(sql)}

  async load(scope:SecretScope,connection:StoredIntegrationConnection){
    if(!connection.secretReference)throw new GoogleReauthenticationRequired();
    const raw=await this.secrets.get(scope,connection.secretReference);
    const token=parseSecret(raw);
    if(!token)throw new GoogleReauthenticationRequired("google-token-secret-invalid");
    return token;
  }

  async getAccessToken(scope:SecretScope,connectionId:string){
    const connection=await this.connections.findScoped(scope,connectionId);
    if(!connection)throw new Error("google-connection-not-found");
    let token=await this.load(scope,connection);
    if(token.expiresAt>Date.now()+60_000)return token.accessToken;
    if(!token.refreshToken){
      await this.connections.updateHealth(scope,connection.id,{state:"needs_reauthentication",message:"Google refresh token is unavailable.",checkedAt:new Date().toISOString()});
      throw new GoogleReauthenticationRequired();
    }

    const response=await this.transport.request({
      url:"https://oauth2.googleapis.com/token",
      method:"POST",
      headers:{"content-type":"application/x-www-form-urlencoded","accept":"application/json"},
      body:formBody({
        client_id:this.oauth.clientId,
        client_secret:this.oauth.clientSecret,
        refresh_token:token.refreshToken,
        grant_type:"refresh_token"
      })
    });
    if(response.status<200||response.status>=300){
      if(response.status===400&&/invalid_grant/i.test(response.body)){
        await this.connections.updateHealth(scope,connection.id,{state:"needs_reauthentication",message:"Google authorization was revoked or expired.",checkedAt:new Date().toISOString()});
        throw new GoogleReauthenticationRequired();
      }
      throw googleHttpError(response);
    }
    const body=parseGoogleJson<any>(response);
    if(typeof body.access_token!=="string")throw new Error("google-refresh-access-token-missing");
    token={
      ...token,
      accessToken:body.access_token,
      expiresAt:Date.now()+Math.max(30,Number(body.expires_in??3600))*1000,
      tokenType:typeof body.token_type==="string"?body.token_type:token.tokenType,
      scopes:typeof body.scope==="string"?body.scope.split(/\s+/).filter(Boolean):token.scopes
    };
    if(!connection.secretReference)throw new GoogleReauthenticationRequired();
    await this.secrets.put(scope,JSON.stringify(token),connection.secretReference);
    return token.accessToken;
  }

  async persistAuthorization(scope:SecretScope,input:{
    accessToken:string;
    refreshToken?:string|null;
    expiresIn?:number;
    tokenType?:string;
    scopes?:string[];
    accountEmail:string;
  }){
    const current=await this.connections.findByIntegration(scope,GOOGLE_INTEGRATION_ID);
    let existing:GoogleTokenSecret|null=null;
    if(current?.secretReference){
      try{existing=await this.load(scope,current)}catch{}
    }
    const token:GoogleTokenSecret={
      accessToken:input.accessToken,
      refreshToken:input.refreshToken??existing?.refreshToken??null,
      expiresAt:Date.now()+Math.max(30,input.expiresIn??3600)*1000,
      tokenType:input.tokenType??"Bearer",
      scopes:input.scopes?.length?input.scopes:[...GOOGLE_SCOPES]
    };
    if(!token.refreshToken)throw new Error("google-refresh-token-missing");
    const reference=await this.secrets.put(scope,JSON.stringify(token),current?.secretReference);
    return this.connections.upsert(scope,{
      integrationId:GOOGLE_INTEGRATION_ID,
      status:"connected",
      externalAccountRef:input.accountEmail,
      secretReference:reference,
      config:{scopes:token.scopes,accountEmail:input.accountEmail}
    });
  }

  async disconnect(scope:SecretScope){
    const current=await this.connections.findByIntegration(scope,GOOGLE_INTEGRATION_ID);
    let revoked=false;
    if(current?.secretReference){
      try{
        const token=await this.load(scope,current);
        const value=token.refreshToken??token.accessToken;
        const response=await this.transport.request({
          url:"https://oauth2.googleapis.com/revoke",
          method:"POST",
          headers:{"content-type":"application/x-www-form-urlencoded","accept":"application/json"},
          body:formBody({token:value})
        });
        revoked=response.status>=200&&response.status<300;
      }catch{}
      await this.secrets.delete(scope,current.secretReference);
    }
    const connection=await this.connections.upsert(scope,{
      integrationId:GOOGLE_INTEGRATION_ID,
      status:"not_configured",
      externalAccountRef:null,
      secretReference:null,
      config:{}
    });
    return{connection,revoked};
  }
}

export interface GoogleHttpRequest{
  url:string;
  method?:"GET"|"POST"|"PUT"|"PATCH"|"DELETE";
  headers?:Record<string,string>;
  body?:string;
  timeoutMs?:number;
}
export interface GoogleHttpResponse{
  status:number;
  body:string;
  headers:Record<string,string>;
}
export interface GoogleHttpTransport{
  request(input:GoogleHttpRequest):Promise<GoogleHttpResponse>;
}

async function readBounded(response:Response,maxBytes=512*1024){
  if(!response.body)return "";
  const reader=response.body.getReader();
  const chunks:Uint8Array[]=[];
  let total=0;
  try{
    while(true){
      const next=await reader.read();
      if(next.done)break;
      total+=next.value.byteLength;
      if(total>maxBytes)throw new Error("google-response-too-large");
      chunks.push(next.value);
    }
  }finally{reader.releaseLock()}
  const merged=new Uint8Array(total);
  let offset=0;for(const chunk of chunks){merged.set(chunk,offset);offset+=chunk.byteLength}
  return new TextDecoder().decode(merged);
}

export class FetchGoogleHttpTransport implements GoogleHttpTransport{
  async request(input:GoogleHttpRequest):Promise<GoogleHttpResponse>{
    const controller=new AbortController();
    const timeout=setTimeout(()=>controller.abort(),Math.max(250,Math.min(30_000,input.timeoutMs??10_000)));
    try{
      let response:Response;
      try{
        response=await fetch(input.url,{
          method:input.method??"GET",
          headers:input.headers,
          body:input.body,
          redirect:"error",
          signal:controller.signal
        });
      }catch(error){
        if(error instanceof Error&&error.name==="AbortError")throw new Error("google-network-timeout");
        throw new Error("google-network-failure");
      }
      const headers:Record<string,string>={};
      response.headers.forEach((value,key)=>{headers[key]=value});
      return{status:response.status,body:await readBounded(response),headers};
    }finally{clearTimeout(timeout)}
  }
}

export function parseGoogleJson<T=Record<string,unknown>>(response:GoogleHttpResponse):T{
  if(!response.body)return{} as T;
  try{return JSON.parse(response.body) as T}catch{throw new Error("google-invalid-json-response")}
}

export function formBody(values:Record<string,string|undefined>){
  const params=new URLSearchParams();
  for(const [key,value] of Object.entries(values))if(value!==undefined)params.set(key,value);
  return params.toString();
}

export function googleHttpError(response:GoogleHttpResponse){
  let reason="";
  try{
    const parsed=JSON.parse(response.body) as any;
    reason=String(parsed?.error?.status??parsed?.error?.message??parsed?.error??"");
  }catch{}
  return new Error(`google-http-${response.status}${reason?":"+reason.slice(0,120):""}`);
}

export type IntegrationState="connected"|"degraded"|"not_configured"|"error"|"needs_reauthentication";
export type IntegrationRisk="low"|"medium"|"high"|"critical";

export interface IntegrationContext{
  tenantId:string;
  workspaceId:string;
  connectionId:string;
}

export interface IntegrationHealth{
  state:IntegrationState;
  message?:string;
  checkedAt:string;
  details?:Record<string,string|number|boolean|null>;
}

export interface IntegrationCapability{
  id:string;
  name:string;
  write:boolean;
  risk:IntegrationRisk;
  requiredScopes:string[];
}

export interface IntegrationExecutionContext extends IntegrationContext{
  actionId:string;
  idempotencyKey:string;
  initiatedBy:string;
  agentId?:string;
}

export interface IntegrationExecutionResult{
  ok:boolean;
  status:number;
  data:Record<string,unknown>;
  externalId?:string;
  idempotencyKey:string;
  completedAt:string;
}

export interface IntegrationAdapter<TConfig=Record<string,unknown>>{
  id:string;
  name:string;
  health(context:IntegrationContext,config:TConfig):Promise<IntegrationHealth>;
  capabilities():IntegrationCapability[];
  execute(actionId:string,input:Record<string,unknown>,context:IntegrationExecutionContext,config:TConfig):Promise<IntegrationExecutionResult>;
}

export class IntegrationAdapterRegistry{
  private readonly adapters=new Map<string,IntegrationAdapter<any>>();
  register(adapter:IntegrationAdapter<any>){this.adapters.set(adapter.id,adapter);return this;}
  get(id:string){return this.adapters.get(id)??null;}
  list(){return [...this.adapters.values()];}
}

export interface AtlasIntegration<TConfig=Record<string,unknown>>{
  id:string;
  name:string;
  actions:IntegrationCapability[];
  health(context:IntegrationContext,config:TConfig):Promise<IntegrationHealth>;
  sync?(context:IntegrationContext,config:TConfig):Promise<{cursor?:string;records:number}>;
  execute?(context:IntegrationContext,actionId:string,input:Record<string,unknown>,config:TConfig):Promise<Record<string,unknown>>;
}

export function assertActionAllowed(integration:{capabilities():IntegrationCapability[]}|AtlasIntegration,actionId:string){
  const actions="capabilities" in integration?integration.capabilities():integration.actions;
  const action=actions.find(item=>item.id===actionId);
